(()=>{
 const E=Engineering,scalar=()=>symbolMarkup('Fparallel','projectionScalar','<msub><mi>F</mi><mo>∥</mo></msub>'),parallel=()=>symbolMarkup('Fparallel','projectionVector','<msub><mstyle mathvariant="bold"><mi>F</mi></mstyle><mo>∥</mo></msub>'),perp=()=>symbolMarkup('Fperp','projectionPerp','<msub><mstyle mathvariant="bold"><mi>F</mi></mstyle><mo>⊥</mo></msub>'),u=()=>vector('u','axisUnit');
 E.symbols({
  axisDirection:['d · directed axis','A nonzero vector defining the positive axis direction. It can be B − A for a rod oriented A→B. Its length does not affect the projection once it is normalized. Reversing it changes the positive direction of the axis.'],
  axisUnit:['u · positive-axis unit vector','The axis direction d divided by |d|. It is dimensionless and must have magnitude 1. The sign of F·u is relative to this chosen positive direction. It is not necessarily the force’s own unit vector.'],
  projectionScalar:['F∥ · signed scalar projection','The signed amount of force along the chosen positive axis, in N: F∥ = F·u. Positive means along u, negative means against u. The component magnitude is |F∥|. This scalar is not a vector.'],
  projectionVector:['F∥ · vector projection','The force vector parallel to the axis, in N: bold F∥ = (F·u)u. Reversing the axis flips both the scalar and u, leaving this vector unchanged. It is one part of the decomposition F = F∥ + F⊥.'],
  projectionPerp:['F⊥ · perpendicular force vector','The remainder F − F∥, in N. It is perpendicular to the specified axis, so F⊥·u = 0. In 3D it may have components along all three Cartesian axes.'],
  thetaProjection:['θ (theta) · angle between force and positive axis','Here θ is the smaller angle, 0–180°, between the force vector F and the positive axis direction u. It is not automatically the angle from +x. F∥ = |F| cos θ. The angle is undefined for zero force.'],
  projectionCos:['cos · projection angle factor','In F∥ = |F| cos θ, θ is between the force and positive axis. Cosine is positive for an acute angle, zero at 90°, and negative for an obtuse angle.'],
  dotProduct:['· (dot) · scalar product','Multiply matching Cartesian components, then add: F·u = Fx ux + Fy uy + Fz uz. The result is a scalar. For projection, u must be a unit vector so the result has force units.']
 },{
  projectionScalar:()=>scalar()+mo('=')+vector('F','Fvector')+symbolMarkup('·','dotProduct','<mo>·</mo>')+u()+mo('=')+mi('F')+mi('cos','projectionCos')+mi('θ','thetaProjection'),
  projectionVector:()=>parallel()+mo('=')+mo('(')+vector('F','Fvector')+mo('·')+u()+mo(')')+u()+mo(' , ')+perp()+mo('=')+vector('F','Fvector')+mo('−')+parallel()
 },[
  {title:'Project a force onto a positive axis',body:'projectionScalar',use:'Find the <strong>signed amount of a force along a rod or axis</strong>.',need:'The <strong>force components (N)</strong> and a <strong>nonzero axis direction</strong>; normalize the axis first. Alternatively, know the force magnitude and the angle between the force and positive axis.',condition:'Use a <strong>unit axis vector</strong> and common perpendicular Cartesian axes. θ is <strong>between the force and axis</strong>, not automatically from +x. Negative projections are valid.',example:'F = <strong>(−100, 50, 0) N</strong> and axis direction <strong>(3, 4, 0)</strong> give u = <strong>(0.6, 0.8, 0)</strong> and F∥ = <strong>−20 N</strong>.',symbols:['Fvector','axisUnit','projectionScalar','thetaProjection','dotProduct']},
  {title:'Find parallel and perpendicular force vectors',body:'projectionVector',use:'Split a force into <strong>a vector along an axis and a perpendicular remainder</strong>.',need:'The <strong>signed scalar projection</strong>, the <strong>axis unit vector</strong>, and the <strong>original force vector</strong>.',condition:'Multiply the scalar by u to restore vector direction. Check <strong>F∥ + F⊥ = F</strong> and <strong>F⊥·u = 0</strong>. Reversing the axis leaves these vectors unchanged.',example:'For F = <strong>(100, 60, 0) N</strong> along the +x axis, F∥ = <strong>(100, 0, 0) N</strong> and F⊥ = <strong>(0, 60, 0) N</strong>.',symbols:['projectionScalar','projectionVector','projectionPerp','axisUnit']}
 ]);
 let state={F:[100,60,0],d:[1,0,0],view:'xy'};
 $('projection').innerHTML=`<div class="lesson-strip"><span class="number">03</span><div><h2>How much force acts along this axis?</h2><p>Normalize the direction. Take the dot product. Restore the vector.</p></div><button id="projectionReset">Reset example</button></div><div class="lab-grid"><article class="panel"><div class="panel-heading"><h3>Force & axis lab</h3><span class="live">● LIVE</span></div><p id="projectionProblem" class="position-problem"></p><label>Diagram view<select id="projectionView"><option value="xy">xy projection</option><option value="xz">xz projection</option><option value="yz">yz projection</option><option value="iso">3D projection</option></select></label><svg id="projectionDiagram" viewBox="0 0 600 400" role="img" aria-label="Force and its parallel and perpendicular projections"></svg><div class="legend"><span class="f1">● Force</span><span class="result">● Parallel</span><span class="f2">● Remainder</span></div><p class="diagram-help">Force arrows use a common scale. The dashed axis indicates direction only. This is a projection; screen lengths and angles may differ from 3D values.</p><div class="coordinate-controls">${E.fields('projectionF','Force components','N',state.F)}${E.fields('projectionD','Positive axis direction d','m',state.d)}</div><div class="actions"><button id="projectionReverse">Reverse positive axis</button><button id="projectionNegative">Negative example</button><button id="projection3D">3D example</button></div><p id="projectionError" class="error" role="status"></p><div id="projectionSummary" class="result-summary" aria-live="polite"></div></article><article class="panel"><h3>Projection, step by step</h3><div class="symbol-help">Tap an <strong>underlined symbol</strong> for its equation-specific meaning.</div><div id="projectionSteps"></div></article></div><article class="panel concept"><h3>Positive, negative, or zero?</h3><div class="concept-grid"><p><strong>Positive:</strong> the force has a component in the chosen positive axis direction. Its angle with that axis is acute.</p><p><strong>Negative:</strong> the component points against the positive axis. Its angle is obtuse. Report the sign unless the problem asks for magnitude only.</p><p><strong>Zero:</strong> a nonzero force is perpendicular to the axis. A zero force also gives zero projection, but has no defined direction angle.</p></div></article><article id="projectionPractice" class="panel position-practice"></article>`;
 function steps(s){const r=M.projection(s.F,s.d),length=vector('d','axisDirection'),dot=symbolMarkup('·','dotProduct','<mo>·</mo>');return E.row(1,'Normalize the positive axis','Axis unit vector',math(u()+mo('=')+fraction(length,mo('|')+length+mo('|')))+math(u()+mo('=')+E.vec(r.unit)),`<strong>Need:</strong> a <strong>nonzero direction d = ${E.tuple(s.d)} m</strong>. Its length is <strong>${E.round(r.axisLength)} m</strong>. Divide each component by this length; u has <strong>no units</strong>.`)+E.row(2,'Calculate the signed scalar projection','Signed force projection',math(scalar()+mo('=')+vector('F','Fvector')+dot+u())+math(scalar()+mo('=')+s.F.map((v,i)=>(i?mo('+'):'')+mo('(')+E.num(v)+mo(')')+mo('(')+E.num(r.unit[i])+mo(')')).join('')+mo('=')+E.num(r.scalar)+E.text(' N')),`<strong>Multiply matching components, then add.</strong> ${Math.abs(r.scalar)<1e-9?'The projection is <strong>zero</strong>.':r.scalar>0?'The component points <strong>along the positive axis</strong>.':'The component points <strong>against the positive axis</strong>.'} Component magnitude: <strong>${E.round(Math.abs(r.scalar))} N</strong>.`)+E.row(3,'Build the parallel vector','Vector projection',math(parallel()+mo('=')+scalar()+u())+math(parallel()+mo('=')+E.vec(r.parallel,'N')),'The <strong>signed scalar times the unit direction</strong> gives a vector in newtons. Reversing the axis flips both signs, so this vector stays the same.')+E.row(4,'Find the perpendicular remainder','Perpendicular force remainder',math(perp()+mo('=')+vector('F','Fvector')+mo('−')+parallel())+math(perp()+mo('=')+E.vec(r.perpendicular,'N')),`<strong>Check:</strong> F∥ + F⊥ = F, and F⊥·u ≈ <strong>${E.round(M.dot(r.perpendicular,r.unit))} N</strong>.`)+E.row(5,'Interpret the angle','Angle between force and positive axis',r.angle===null?'Angle undefined: the force is zero.':math(mi('θ','thetaProjection')+mo('=')+'<msup><mi>cos</mi><mn>−1</mn></msup>'+mo('(')+fraction(scalar(),mo('|')+vector('F','Fvector')+mo('|'))+mo(')')+mo('=')+E.num(r.angle)+mo('°')),'Here θ is <strong>between the force and the chosen positive axis</strong>. It is not necessarily the angle from +x.');}
 function render(){try{const r=M.projection(state.F,state.d),span=Math.max(r.forceLength,1)*1.25,unitExtent=r.unit.map(v=>v*span);$('projectionProblem').innerHTML=`Project <strong>F = ${E.tuple(state.F)} N</strong> onto the axis whose positive direction is <strong>d = ${E.tuple(state.d)} m</strong>.`;$('projectionSteps').innerHTML=steps(state);$('projectionSummary').innerHTML=`<div><small>SIGNED COMPONENT</small>${E.round(r.scalar)} N</div><div><small>ANGLE TO +AXIS</small>${r.angle===null?'Undefined':E.round(r.angle)+'°'}</div>`;$('projectionError').textContent='';E.diagram('projectionDiagram',state.view,[{start:unitExtent.map(v=>-v),end:unitExtent,color:'#617384',label:'+axis',dashed:true},{start:[0,0,0],end:state.F,color:'#8cbcff',label:'F',arrow:true},{start:[0,0,0],end:r.parallel,color:'#b4f178',label:'F∥',arrow:true},{start:r.parallel,end:state.F,color:'#efbd77',label:'F⊥',arrow:true}]);}catch(e){$('projectionError').textContent=e.message;$('projectionSteps').innerHTML='';$('projectionSummary').innerHTML='';$('projectionDiagram').innerHTML='';}}
 function sync(){E.sync('projectionF',state.F);E.sync('projectionD',state.d);$('projectionView').value=state.view;}
 for(const id of ['projectionF','projectionD'])E.axes.forEach((_,i)=>$(id+i).addEventListener('input',()=>{try{[state.F,state.d]=E.read(['projectionF','projectionD']);render();}catch(e){$('projectionError').textContent=e.message;}}));
 $('projectionView').onchange=()=>{state.view=$('projectionView').value;render();};$('projectionReset').onclick=()=>{state={F:[100,60,0],d:[1,0,0],view:'xy'};sync();render();};$('projectionReverse').onclick=()=>{state.d=state.d.map(v=>-v);sync();render();};$('projectionNegative').onclick=()=>{state={F:[-100,50,0],d:[3,4,0],view:'xy'};sync();render();};$('projection3D').onclick=()=>{state={F:[100,-50,200],d:[2,1,2],view:'iso'};sync();render();};
 const cases=[{name:'Positive projection',F:[100,50,0],d:[3,4,0]},{name:'Negative projection',F:[-100,50,0],d:[3,4,0]},{name:'Perpendicular force',F:[-80,60,0],d:[3,4,0]},{name:'3D force',F:[100,-50,200],d:[2,1,2]}].map(c=>({...c,problem:`Find the <strong>signed scalar projection</strong> and <strong>parallel vector components</strong> for <strong>F = ${E.tuple(c.F)} N</strong> onto <strong>d = ${E.tuple(c.d)} m</strong>.`,feedback:'Normalize the axis first. Keep the scalar’s sign, then multiply it by each unit-vector component. Answers within 0.1 N are accepted.'}));
 E.practice({id:'projectionPractice',title:'Separate the scalar from the vector.',cases,targets:c=>{const r=M.projection(c.F,c.d);return [{label:'Signed F∥ (N)',value:r.scalar,tolerance:.1},...r.parallel.map((v,i)=>({label:`Parallel F${E.axes[i]} (N)`,value:v,tolerance:.1}))];},solution:steps,hints:['First form u = d / |d|. Do not dot the force with an unnormalized axis.','F∥ = Fx ux + Fy uy + Fz uz. An obtuse angle gives a negative scalar.','For the parallel vector, multiply F∥ by ux, uy, uz individually.']});render();
})();
